server.js<pre><code>import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';

const server = createServer(async (req, res) =&gt; {
  const body = await readFile(new URL('./hello.txt', import.meta.url));
  res.writeHead(200, { 'content-type': 'text/plain' });
  res.end(body);
});

server.listen(3000, () =&gt; console.log('listening on http://localhost:3000'));
</code></pre> <p>Step by step:</p> <ol> <li><code>node</code> starts, initializes V8 and libuv, and loads <code>server.js</code> as an ES module.</li> <li>Your top-level code runs: it creates a server and calls <code>listen</code>. libuv opens a    listening socket and registers it with the OS poller. Top-level code ends.</li> <li>The event loop starts. Because there is an active handle (the listening socket),    the process stays alive instead of exiting.</li> <li>A request arrives. The OS marks the socket readable; libuv's poll phase notices,    Node's HTTP parser (llhttp) parses the bytes, and your handler is called.</li> <li><code>readFile</code> hands the read to the thread pool and returns a pending promise. Your    handler pauses at <code>await</code>. The main thread is free to serve other requests.</li> <li>A pool thread finishes the read, libuv queues the completion, and the loop resumes    your function with the file contents. You write the response; libuv sends it.</li> </ol> <p>Create <code>hello.txt</code>, run <code>node server.js</code>, and <code>curl localhost:3000</code>.</p>

math.mjs<pre><code>export const PI = 3.14159;
export function area(r) { return PI * r * r; }
export default function describe() { return 'geometry helpers'; }
</code></pre> main.mjs<pre><code>import describe, { area } from './math.mjs';     // default + named
import * as math from './math.mjs';              // namespace object
import { readFile } from 'node:fs/promises';     // built-in, with node: prefix

const config = JSON.parse(await readFile(new URL('./config.json', import.meta.url), 'utf8'));
const { default: lazy } = await import('./math.mjs'); // dynamic import, returns a promise
</code></pre> <p>Rules that trip people up in ESM:</p> <ul> <li>Relative imports need the file extension: <code>'./math.js'</code>, not <code>'./math'</code>. ESM   resolution in Node does not guess extensions or look for <code>index.js</code>.</li> <li>No <code>__dirname</code>, <code>__filename</code>, or <code>require</code> by default. Use <code>import.meta.dirname</code>   and <code>import.meta.filename</code> (available in current Node releases), or <code>import.meta.url</code>   with <code>new URL(...)</code>.</li> <li>Top-level <code>await</code> works — handy for loading config at startup.</li> <li>ESM is always in strict mode.</li> </ul>

legacy.cjs<pre><code>const path = require('node:path');
exports.greet = (name) =&gt; `hello, ${name}`;
exports.version = 1;
// or: module.exports = { greet, version };
</code></pre> <p><code>require</code> is synchronous and can be called anywhere, including inside <code>if</code> blocks. <code>__dirname</code> and <code>__filename</code> exist in every CommonJS module.</p>

package.json<pre><code>{
  "name": "orders-api",
  "version": "0.3.0",
  "private": true,
  "type": "module",
  "main": "src/server.js",
  "engines": { "node": "&gt;=22" },
  "scripts": {
    "start": "node src/server.js",
    "dev": "node --watch --env-file=.env src/server.js",
    "test": "node --test",
    "lint": "eslint .",
    "check": "npm run lint &amp;&amp; npm test"
  },
  "dependencies": {
    "express": "^5.1.0",
    "pino": "^10.0.0"
  },
  "devDependencies": {
    "eslint": "^9.0.0",
    "supertest": "^7.0.0"
  }
}
</code></pre> <p>Field by field:</p> <ul> <li><code>"private": true</code> prevents an accidental <code>npm publish</code> of an application.</li> <li><code>"type": "module"</code> makes <code>.js</code> files ES modules (lesson 03).</li> <li><code>scripts</code> are named shell commands. <code>npm start</code> and <code>npm test</code> are shortcuts; anything   else runs with <code>npm run &lt;name&gt;</code>.</li> <li><code>dependencies</code> are needed at runtime. <code>devDependencies</code> are only needed to develop,   test, or build. In production installs (<code>npm ci --omit=dev</code>) they are skipped, which   shrinks your container image.</li> </ul>

paths.mjs<pre><code>import path from 'node:path';

console.log(path.join('/srv/app', 'uploads', '../logs', 'app.log'));
console.log(path.parse('/srv/app/logs/app.2024-01-01.log'));
console.log(path.extname('archive.tar.gz'), path.basename('/a/b/report.pdf', '.pdf'));
console.log(path.relative('/srv/app/src', '/srv/app/public/index.html'));
</code></pre> <pre><code>/srv/app/logs/app.log
{
  root: '/',
  dir: '/srv/app/logs',
  base: 'app.2024-01-01.log',
  ext: '.log',
  name: 'app.2024-01-01'
}
.gz report
../public/index.html
</code></pre> <ul> <li><code>path.join</code> concatenates and normalizes (resolves <code>..</code>, removes duplicate slashes).</li> <li><code>path.resolve</code> produces an absolute path, resolving relative segments against   <code>process.cwd()</code> — the directory you ran <code>node</code> from, not the script's directory.</li> <li>Use <code>path.posix</code> / <code>path.win32</code> explicitly if you must produce a specific style.</li> </ul> <p>To refer to a file next to your module regardless of where <code>node</code> was launched from, use <code>import.meta.dirname</code>:</p> <pre><code>const templatePath = path.join(import.meta.dirname, 'templates', 'email.html');
</code></pre>

async.mjs<pre><code>import { setTimeout as sleep } from 'node:timers/promises';

// Pretend these are network calls with different latencies
async function fetchUser(id) { await sleep(100); return { id, name: `user${id}` }; }
async function fetchOrders(id) { await sleep(150); return [{ id: 1, userId: id }]; }
async function fetchFlaky() { await sleep(50); throw new Error('recommendations service down'); }

let t = performance.now();
const user = await fetchUser(7);
const orders = await fetchOrders(7);
console.log('sequential:', Math.round(performance.now() - t), 'ms');

t = performance.now();
const [u2, o2] = await Promise.all([fetchUser(7), fetchOrders(7)]);
console.log('parallel:  ', Math.round(performance.now() - t), 'ms');

const results = await Promise.allSettled([fetchUser(7), fetchFlaky()]);
console.log(results.map(r =&gt; r.status));

try {
  await sleep(1000, null, { signal: AbortSignal.timeout(200) });
} catch (err) {
  console.log('aborted:', err.name);
}
</code></pre> <pre><code>sequential: 255 ms
parallel:   150 ms
[ 'fulfilled', 'rejected' ]
aborted: AbortError
</code></pre> <p>Takeaways:</p> <ul> <li>Two independent <code>await</code>s in a row take the sum of their times. Start both, then   await them together with <code>Promise.all</code> to take the max.</li> <li><code>Promise.all</code> rejects as soon as any input rejects. Use <code>Promise.allSettled</code> when a   page can render with partial data.</li> <li><code>Promise.race</code> settles with the first to settle; <code>Promise.any</code> with the first to   succeed.</li> <li><code>AbortSignal</code> is Node's standard cancellation mechanism. <code>fetch</code>, <code>timers/promises</code>,   <code>fs.readFile</code>, <code>events.once</code>, streams, and child processes accept <code>{ signal }</code>.   <code>AbortSignal.timeout(ms)</code> creates one that fires automatically.</li> </ul>

http-server.mjs<pre><code>import { createServer } from 'node:http';

const notes = new Map();
let nextId = 1;
const MAX_BODY = 10_000; // bytes

function sendJson(res, status, data) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(body),
  });
  res.end(body);
}

async function readJsonBody(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size &gt; MAX_BODY) throw Object.assign(new Error('body too large'), { status: 413 });
    chunks.push(chunk);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString('utf8'));
  } catch {
    throw Object.assign(new Error('invalid JSON'), { status: 400 });
  }
}

const server = createServer(async (req, res) =&gt; {
  const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
  const match = url.pathname.match(/^\/notes\/(\d+)$/);

  try {
    if (req.method === 'GET' &amp;&amp; url.pathname === '/notes') {
      const q = url.searchParams.get('q')?.toLowerCase();
      const list = [...notes.values()].filter(n =&gt; !q || n.text.toLowerCase().includes(q));
      return sendJson(res, 200, list);
    }
    if (req.method === 'POST' &amp;&amp; url.pathname === '/notes') {
      const { text } = await readJsonBody(req);
      if (typeof text !== 'string' || !text.trim()) return sendJson(res, 400, { error: 'text is required' });
      const note = { id: nextId++, text: text.trim() };
      notes.set(note.id, note);
      res.setHeader('location', `/notes/${note.id}`);
      return sendJson(res, 201, note);
    }
    if (req.method === 'GET' &amp;&amp; match) {
      const note = notes.get(Number(match[1]));
      return note ? sendJson(res, 200, note) : sendJson(res, 404, { error: 'not found' });
    }
    if (req.method === 'DELETE' &amp;&amp; match) {
      const existed = notes.delete(Number(match[1]));
      res.writeHead(existed ? 204 : 404).end();
      return;
    }
    sendJson(res, 404, { error: `no route for ${req.method} ${url.pathname}` });
  } catch (err) {
    sendJson(res, err.status ?? 500, { error: err.status ? err.message : 'internal error' });
    if (!err.status) console.error(err);
  }
});

server.listen(3000, () =&gt; console.log('notes API on http://localhost:3000'));
</code></pre> <p>Exercising it with <code>curl</code>:</p> <pre><code>curl -i -X POST localhost:3000/notes -H 'content-type: application/json' -d '{"text":"buy milk"}'
</code></pre> <pre><code>HTTP/1.1 201 Created
location: /notes/1
content-type: application/json; charset=utf-8
content-length: 26
Date: ...
Connection: keep-alive
Keep-Alive: timeout=5

{"id":1,"text":"buy milk"}
</code></pre> <p>Then, after adding a second note:</p> <pre><code>$ curl 'localhost:3000/notes?q=milk'
[{"id":1,"text":"buy milk"}]
$ curl -X POST localhost:3000/notes -d '{oops'
{"error":"invalid JSON"}
$ curl -o /dev/null -w "%{http_code}\n" -X DELETE localhost:3000/notes/1
204
$ curl localhost:3000/notes/1
{"error":"not found"}
$ curl localhost:3000/users
{"error":"no route for GET /users"}
</code></pre>

package.json<pre><code>{
  "name": "logstat",
  "version": "1.0.0",
  "type": "module",
  "bin": { "logstat": "./bin/logstat.js" },
  "engines": { "node": "&gt;=22" }
}
</code></pre> <p><code>bin</code> maps a command name to a file. On <code>npm install -g</code> or <code>npm link</code>, npm creates a <code>logstat</code> executable on your <code>PATH</code> pointing at that file.</p>

src/parse.js<pre><code>// Matches the common/combined access-log format used by nginx and Apache:
// 203.0.113.9 - - [10/Oct/2025:13:55:36 +0000] "GET /api/users HTTP/1.1" 200 512 ...
const LINE = /^(\S+) \S+ \S+ \[([^\]]+)\] "(\S+) (\S+) [^"]*" (\d{3}) (\d+|-)/;

export function parseLine(line) {
  const m = LINE.exec(line);
  if (!m) return null;
  const [, ip, time, method, url, status, bytes] = m;
  return {
    ip, time, method,
    path: url.split('?')[0],
    status: Number(status),
    bytes: bytes === '-' ? 0 : Number(bytes),
  };
}
</code></pre> <p>The regex captures the fields we need from the common/combined log format; anything that doesn't match returns <code>null</code> so the caller can count it as invalid rather than crash.</p>

src/stats.js<pre><code>export function createStats() {
  return { total: 0, invalid: 0, bytes: 0, byStatus: new Map(), byPath: new Map() };
}

export function addEntry(stats, entry) {
  stats.total++;
  stats.bytes += entry.bytes;
  const cls = `${Math.floor(entry.status / 100)}xx`;
  stats.byStatus.set(cls, (stats.byStatus.get(cls) ?? 0) + 1);
  stats.byPath.set(entry.path, (stats.byPath.get(entry.path) ?? 0) + 1);
}

export function summarize(stats, top) {
  return {
    requests: stats.total,
    invalidLines: stats.invalid,
    bytes: stats.bytes,
    status: Object.fromEntries([...stats.byStatus].sort()),
    topPaths: [...stats.byPath]
      .sort((a, b) =&gt; b[1] - a[1])
      .slice(0, top)
      .map(([path, count]) =&gt; ({ path, count })),
  };
}
</code></pre> <p><code>Map</code> is used instead of a plain object for counts: keys like <code>/constructor</code> or <code>__proto__</code> in a URL would collide with object prototype properties.</p>

bin/logstat.js<pre><code>#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { createReadStream } from 'node:fs';
import { createInterface } from 'node:readline';
import { parseLine } from '../src/parse.js';
import { createStats, addEntry, summarize } from '../src/stats.js';

const HELP = `Usage: logstat [options] [file]

Summarize an nginx/Apache access log. Reads stdin if no file is given.

Options:
  -t, --top &lt;n&gt;       number of top paths to show (default 5)
  -s, --status &lt;cls&gt;  only count this status class, e.g. 5xx
  -j, --json          print JSON instead of a table
  -h, --help          show this help`;

let args;
try {
  args = parseArgs({
    allowPositionals: true,
    options: {
      top: { type: 'string', short: 't', default: '5' },
      status: { type: 'string', short: 's' },
      json: { type: 'boolean', short: 'j', default: false },
      help: { type: 'boolean', short: 'h', default: false },
    },
  });
} catch (err) {
  console.error(`logstat: ${err.message}\n\n${HELP}`);
  process.exit(2);
}

const { values, positionals } = args;
if (values.help) {
  console.log(HELP);
  process.exit(0);
}

const top = Number.parseInt(values.top, 10);
if (!Number.isInteger(top) || top &lt; 1) {
  console.error('logstat: --top must be a positive integer');
  process.exit(2);
}

const file = positionals[0];
const input = file ? createReadStream(file) : process.stdin;
input.on('error', (err) =&gt; {
  console.error(`logstat: cannot read ${file}: ${err.code ?? err.message}`);
  process.exit(1);
});

const stats = createStats();
const rl = createInterface({ input, crlfDelay: Infinity });
for await (const line of rl) {
  if (!line.trim()) continue;
  const entry = parseLine(line);
  if (!entry) { stats.invalid++; continue; }
  if (values.status &amp;&amp; `${Math.floor(entry.status / 100)}xx` !== values.status) continue;
  addEntry(stats, entry);
}

const summary = summarize(stats, top);
if (values.json) {
  console.log(JSON.stringify(summary, null, 2));
} else {
  console.log(`requests: ${summary.requests}  bytes: ${summary.bytes}  invalid lines: ${summary.invalidLines}`);
  console.log('status classes:', Object.entries(summary.status).map(([k, v]) =&gt; `${k}=${v}`).join(' '));
  console.log('top paths:');
  console.table(summary.topPaths);
}
</code></pre> <p>Key decisions:</p> <ul> <li><code>#!/usr/bin/env node</code> (the shebang) lets the OS run the file directly after   <code>chmod +x</code>. On Windows, npm generates a <code>.cmd</code> wrapper instead.</li> <li><code>util.parseArgs</code> is Node's built-in flag parser. It rejects unknown options when   <code>strict</code> (the default), which we turn into exit code 2 plus the help text.</li> <li><code>readline.createInterface</code> over a stream yields one line at a time with   <code>for await</code>, so a 5 GB log uses a few kilobytes of memory.</li> <li>The stream's <code>'error'</code> handler turns <code>ENOENT</code> into a friendly message and exit code 1.</li> </ul>

test/parse.test.js<pre><code>import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseLine } from '../src/parse.js';

test('parses a combined-format line', () =&gt; {
  const e = parseLine('203.0.113.9 - - [10/Oct/2025:13:55:36 +0000] "GET /api/users?page=2 HTTP/1.1" 200 512 "-" "curl/8.0"');
  assert.deepEqual(e, {
    ip: '203.0.113.9', time: '10/Oct/2025:13:55:36 +0000', method: 'GET',
    path: '/api/users', status: 200, bytes: 512,
  });
});

test('treats "-" bytes as 0', () =&gt; {
  assert.equal(parseLine('1.2.3.4 - - [x] "GET / HTTP/1.1" 404 - "-" "-"').bytes, 0);
});

test('returns null for garbage', () =&gt; {
  assert.equal(parseLine('this line is garbage'), null);
});
</code></pre> <pre><code>$ node --test
✔ parses a combined-format line
✔ treats "-" bytes as 0
✔ returns null for garbage
ℹ tests 3
ℹ pass 3
ℹ fail 0
</code></pre> <p><code>node --test</code> with no arguments finds files matching common patterns such as <code>*.test.js</code> under <code>test/</code>. Level 2 covers the test runner properly.</p>

app.js<pre><code>import express from 'express';

const app = express();
app.use(express.json());                     // parse JSON bodies into req.body

app.get('/health', (req, res) =&gt; {
  res.json({ status: 'ok' });                // sets content-type and serializes
});

app.post('/echo', (req, res) =&gt; {
  res.status(201).json({ youSent: req.body });
});

app.listen(3000, () =&gt; console.log('http://localhost:3000'));
</code></pre> <p>Compare with Level 1: <code>res.json</code> replaces the <code>sendJson</code> helper, <code>express.json()</code> replaces <code>readJsonBody</code> (with a default 100 KB limit), and <code>app.get(path, fn)</code> replaces the <code>if</code> chain.</p>

schemas.js<pre><code>import { z } from 'zod';

