  email: 'ada@example.com',
  name: 'Ada',
  age: 36,
  role: 'member',
  tags: []
}
</code></pre> <p><code>parse</code> returned a new object: the name was trimmed, <code>'36'</code> was coerced to <code>36</code>, and defaults were filled in. Use the parsed output, not the original input.</p>

src/errors.js<pre><code>export class HttpError extends Error {
  constructor(status, message, details) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
    this.details = details;
  }
}

export const badRequest = (msg, details) =&gt; new HttpError(400, msg, details);
export const unauthorized = (msg = 'authentication required') =&gt; new HttpError(401, msg);
export const notFound = (msg = 'not found') =&gt; new HttpError(404, msg);
export const conflict = (msg) =&gt; new HttpError(409, msg);

// Express 5: registered last, with four parameters
export function errorHandler(err, req, res, next) {
  if (res.headersSent) return next(err);

  // body-parser errors (malformed JSON, too large) carry a status and `expose`
  if (err.type === 'entity.parse.failed') err = badRequest('malformed JSON body');
  const status = err.status ?? 500;

  if (status &gt;= 500) req.log.error({ err }, 'unhandled error');
  else req.log.warn({ status, msg: err.message }, 'request failed');

  res.status(status).json({
    error: status &gt;= 500 ? 'internal server error' : err.message,
    ...(err.details &amp;&amp; { details: err.details }),
  });
}
</code></pre> <p>Route handlers now read naturally — they <code>throw</code> and move on:</p> <pre><code>router.get('/:id', validate({ params: idParams }), async (req, res) =&gt; {
  const task = await findTask(req.valid.params.id, req.user.id);
  if (!task) throw notFound('task not found');
  res.json(task);
});
</code></pre> <p>Registration order at the end of <code>createApp</code>:</p> <pre><code>app.use((req, res, next) =&gt; next(notFound(`no route for ${req.method} ${req.path}`)));
app.use(errorHandler);
</code></pre> <p>The catch-all 404 comes after every router; the error handler comes last of all.</p>

src/db.js<pre><code>import { Kysely, PostgresDialect } from 'kysely';
import pg from 'pg';

export function createDb({ connectionString, pool } = {}) {
  return new Kysely({
    dialect: new PostgresDialect({ pool: pool ?? new pg.Pool({ connectionString, max: 10 }) }),
  });
}
</code></pre> <p>Create one <code>Kysely</code> instance (one pool) per process at startup and pass it to your routers. Call <code>db.destroy()</code> on shutdown to close connections.</p>

queries.js<pre><code>const user = await db.insertInto('users').values({ email: 'ada@example.com' })
  .returning(['id', 'email']).executeTakeFirstOrThrow();
console.log(user);

await db.insertInto('tasks').values([
  { user_id: user.id, title: 'write migration' },
  { user_id: user.id, title: 'add index', done: true },
]).execute();

const q = db.selectFrom('tasks')
  .innerJoin('users', 'users.id', 'tasks.user_id')
  .select(['tasks.id', 'tasks.title', 'users.email'])
  .where('tasks.done', '=', false)
  .orderBy('tasks.id');
console.log(q.compile().sql);
console.log(await q.execute());

const res = await db.updateTable('tasks').set({ done: true }).where('id', '=', 1).executeTakeFirst();
console.log('updated rows:', res.numUpdatedRows);

try {
  await db.insertInto('users').values({ email: 'ada@example.com' }).execute();
} catch (e) { console.log('duplicate:', e.code, e.message); }
</code></pre> <pre><code>{ id: 1, email: 'ada@example.com' }
select "tasks"."id", "tasks"."title", "users"."email" from "tasks" inner join "users" on "users"."id" = "tasks"."user_id" where "tasks"."done" = $1 order by "tasks"."id"
[ { id: 1, title: 'write migration', email: 'ada@example.com' } ]
updated rows: 1n
duplicate: 23505 duplicate key value violates unique constraint "users_email_key"
</code></pre> <p>Look at the compiled SQL: the value <code>false</code> became <code>$1</code>. Kysely never splices values into SQL text; it sends them separately as parameters. That is what makes it immune to SQL injection for values. (Identifiers — table and column names — are a different story: never build them from user input.)</p> <p><code>numUpdatedRows</code> is a <code>BigInt</code> (<code>1n</code>), since row counts can exceed 2^53.</p>

src/retry.js<pre><code>import { setTimeout as sleep } from 'node:timers/promises';

// Retry an async function with exponential backoff
export async function retry(fn, { attempts = 3, baseMs = 100 } = {}) {
  let lastErr;
  for (let i = 0; i &lt; attempts; i++) {
    try {
      return await fn(i);
    } catch (err) {
      lastErr = err;
      if (i &lt; attempts - 1) await sleep(baseMs * 2 ** i);
    }
  }
  throw lastErr;
}
</code></pre> test/retry.test.js<pre><code>import { test, mock } from 'node:test';
import assert from 'node:assert/strict';
import { retry } from './retry.js';

test('returns the first successful result', async () =&gt; {
  const fn = mock.fn(async () =&gt; 'ok');
  assert.equal(await retry(fn), 'ok');
  assert.equal(fn.mock.callCount(), 1);
});

test('retries until success', async () =&gt; {
  let calls = 0;
  const fn = mock.fn(async () =&gt; {
    if (++calls &lt; 3) throw new Error('flaky');
    return 'finally';
  });
  assert.equal(await retry(fn, { baseMs: 1 }), 'finally');
  assert.equal(fn.mock.callCount(), 3);
});

test('gives up after the last attempt and rethrows', async () =&gt; {
  const fn = mock.fn(async () =&gt; { throw new Error('down'); });
  await assert.rejects(retry(fn, { attempts: 2, baseMs: 1 }), /down/);
  assert.equal(fn.mock.callCount(), 2);
});
</code></pre> <pre><code>$ node --test --experimental-test-coverage 'test/*.test.js'
✔ returns the first successful result (1.6ms)
✔ retries until success (4.8ms)
✔ gives up after the last attempt and rethrows (2.1ms)
ℹ tests 3
ℹ pass 3
ℹ fail 0
ℹ file      | line % | branch % | funcs % | uncovered lines
ℹ  retry.js | 100.00 |   100.00 |  100.00 |
</code></pre> <p>What's being used:</p> <ul> <li><code>mock.fn(impl)</code> wraps a function and records calls (<code>fn.mock.callCount()</code>,   <code>fn.mock.calls[0].arguments</code>).</li> <li><code>assert/strict</code> makes <code>equal</code> use <code>===</code> and <code>deepEqual</code> strict deep equality.</li> <li><code>assert.rejects(promise, /pattern/)</code> for async failures.</li> <li>Passing a tiny <code>baseMs</code> keeps the backoff test fast. For code that uses real timers   with long delays, <code>mock.timers.enable({ apis: ['setTimeout'] })</code> lets you advance time   with <code>mock.timers.tick(ms)</code>.</li> </ul> <p>Useful runner flags: <code>--watch</code> (re-run on change), <code>--test-name-pattern="retries"</code>, <code>--test-only</code> with <code>test.only(...)</code>, and <code>--test-concurrency</code>. File arguments are paths or glob patterns; with no arguments, <code>node --test</code> searches for common test-file names.</p>

