child.mjs<pre><code>import { execFile, spawn } from 'node:child_process';
import { promisify } from 'node:util';

const execFileP = promisify(execFile);

// 1. Run a command, collect its output (bounded by maxBuffer)
const { stdout } = await execFileP('node', ['-p', 'process.version'], { timeout: 5_000 });
console.log('child node version:', stdout.trim());

// 2. Stream a long-running process's output line by line
const child = spawn('node', ['-e', `
  for (let i = 1; i &lt;= 3; i++) setTimeout(() =&gt; console.log('progress ' + i * 33 + '%'), i * 100);
  setTimeout(() =&gt; { console.error('warning: disk almost full'); process.exit(3); }, 400);
`]);
child.stdout.setEncoding('utf8').on('data', (d) =&gt; process.stdout.write(`[child] ${d}`));
child.stderr.setEncoding('utf8').on('data', (d) =&gt; process.stdout.write(`[child stderr] ${d}`));
const [code] = await new Promise((resolve, reject) =&gt; {
  child.once('error', reject);                // e.g. ENOENT: command not found
  child.once('close', (...args) =&gt; resolve(args));
});
console.log('child exited with code', code);

// 3. Arguments are passed as an array: no shell, so no injection
const filename = 'report; rm -rf ~';          // hostile input stays one harmless argument
const r = await execFileP('node', ['-p', 'process.argv[1]', filename]);
console.log('argument received literally:', r.stdout.trim());
</code></pre> <pre><code>child node version: v26.3.0
[child] progress 33%
[child] progress 66%
[child] progress 99%
[child stderr] warning: disk almost full
child exited with code 3
argument received literally: report; rm -rf ~
</code></pre> <p>Choosing the function:</p> Function Shell? Output Use for <code>execFile(cmd, args)</code> no buffered (limit: <code>maxBuffer</code>) short commands with small output <code>spawn(cmd, args)</code> no (unless <code>shell: true</code>) streams long-running or large output <code>exec('cmd string')</code> yes buffered only with fully trusted, constant strings <code>fork(modulePath)</code> no streams + IPC channel another Node process you control <p>Never pass user input to <code>exec</code> or <code>spawn(..., { shell: true })</code>. A filename of <code>report; rm -rf ~</code> becomes two shell commands. With <code>execFile</code>/<code>spawn</code> and an argument array, as the last example shows, the hostile string arrives as one literal argument.</p> <p><code>fork()</code> starts a Node script with a built-in message channel (<code>child.send(obj)</code> / <code>process.on('message')</code>), useful when you want process-level isolation — a crash or memory leak in the child can't take down the parent.</p>

cluster.mjs<pre><code>import cluster from 'node:cluster';
import { createServer } from 'node:http';
import { availableParallelism } from 'node:os';

const WORKERS = Number(process.env.WORKERS ?? availableParallelism());

if (cluster.isPrimary) {
  console.log(`primary ${process.pid} starting ${WORKERS} workers`);
  for (let i = 0; i &lt; WORKERS; i++) cluster.fork();

  cluster.on('exit', (worker, code, signal) =&gt; {
    if (worker.exitedAfterDisconnect) return;          // intentional shutdown
    console.log(`worker ${worker.process.pid} died (${signal ?? code}); starting a replacement`);
    cluster.fork();
  });

  process.on('SIGTERM', () =&gt; {
    for (const w of Object.values(cluster.workers)) w.disconnect();  // finish in-flight, then exit
  });
} else {
  createServer((req, res) =&gt; {
    if (req.url === '/crash') process.exit(1);          // simulate a fatal bug
    res.end(`handled by worker ${process.pid}\n`);
  }).listen(3200);
}
