server.js<pre><code>import { createServer } from 'node:http';
import { WebSocketServer } from 'ws';

const server = createServer((req, res) =&gt; res.end('ok'));
const wss = new WebSocketServer({ server, path: '/ws', maxPayload: 64 * 1024 });

wss.on('connection', (socket, req) =&gt; {
  socket.isAlive = true;
  socket.on('pong', () =&gt; { socket.isAlive = true; });
  socket.on('error', (err) =&gt; console.error('socket error', err.message));

  socket.on('message', (data, isBinary) =&gt; {
    if (isBinary) return socket.close(1003, 'text only');
    let msg;
    try { msg = JSON.parse(data.toString()); } catch { return socket.close(1007, 'invalid JSON'); }
    // Broadcast to every open client (including the sender)
    const out = JSON.stringify({ from: req.socket.remotePort, text: String(msg.text).slice(0, 500) });
    for (const client of wss.clients) {
      if (client.readyState === client.OPEN) client.send(out);
    }
  });
  socket.send(JSON.stringify({ system: `welcome, ${wss.clients.size} connected` }));
});

// Heartbeat: terminate connections that stop answering pings (dead NAT paths, sleeping laptops)
const interval = setInterval(() =&gt; {
  for (const socket of wss.clients) {
    if (!socket.isAlive) { socket.terminate(); continue; }
    socket.isAlive = false;
    socket.ping();
  }
}, 30_000);
wss.on('close', () =&gt; clearInterval(interval));

server.listen(3300, () =&gt; console.log('ws://localhost:3300/ws'));
</code></pre> <p>And a client script using the global <code>WebSocket</code>:</p> client.js<pre><code>// Uses the WebSocket client built into current Node releases (same API as browsers)
function connect(name) {
  return new Promise((resolve) =&gt; {
    const ws = new WebSocket('ws://localhost:3300/ws');
    ws.addEventListener('message', (e) =&gt; console.log(`${name} got:`, e.data));
    ws.addEventListener('open', () =&gt; resolve(ws));
  });
}
const alice = await connect('alice');
const bob = await connect('bob');
alice.send(JSON.stringify({ text: 'hi bob' }));
setTimeout(() =&gt; { alice.close(); bob.close(); }, 200);
</code></pre> <pre><code>alice got: {"system":"welcome, 1 connected"}
bob got: {"system":"welcome, 2 connected"}
alice got: {"from":50660,"text":"hi bob"}
bob got: {"from":50660,"text":"hi bob"}
</code></pre> <p>Details that matter in the server:</p> <ul> <li>Shared HTTP server. The WebSocket server attaches to a normal <code>http.Server</code>, so   one port serves both your REST API and <code>/ws</code>. With Express, pass the server returned by   <code>app.listen()</code>.</li> <li><code>maxPayload</code> caps message size (the <code>ws</code> default is much larger); a client sending a   100 MB frame is rejected instead of buffered.</li> <li>Validate every message. Treat incoming frames exactly like request bodies: parse   defensively, check the schema (Zod works fine here), limit lengths. Close codes like   <code>1003</code> (unsupported data) and <code>1007</code> (invalid payload) tell well-behaved clients why.</li> <li>Heartbeats. A TCP connection can die silently — a phone switches networks, a NAT   entry times out — and neither side notices until it tries to send. Periodic pings with   a pong check find and clean up dead sockets; otherwise your <code>clients</code> set leaks.</li> <li>Check <code>readyState</code> before sending, and add an <code>'error'</code> listener on each socket.</li> </ul>

app.js<pre><code>import express from 'express';
import multer from 'multer';
import { randomUUID } from 'node:crypto';
import { open, rm, mkdir } from 'node:fs/promises';
import path from 'node:path';

const UPLOAD_DIR = path.join(import.meta.dirname, 'uploads');
await mkdir(UPLOAD_DIR, { recursive: true });

const upload = multer({
  storage: multer.diskStorage({
    destination: UPLOAD_DIR,
    // Never use the client's filename on disk: generate our own
    filename: (req, file, cb) =&gt; cb(null, randomUUID()),
  }),
  limits: { fileSize: 2 * 1024 * 1024, files: 1, fields: 5 },
});

// Check the actual bytes, not the client-supplied mimetype or extension
const SIGNATURES = {
  'image/png': Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
  'image/jpeg': Buffer.from([0xff, 0xd8, 0xff]),
};
async function sniffType(filePath) {
  const fh = await open(filePath, 'r');
  try {
    const { buffer } = await fh.read(Buffer.alloc(8), 0, 8, 0);
    return Object.entries(SIGNATURES).find(([, sig]) =&gt; buffer.subarray(0, sig.length).equals(sig))?.[0] ?? null;
  } finally {
    await fh.close();
  }
}

export const app = express();

app.post('/avatars', upload.single('avatar'), async (req, res) =&gt; {
  if (!req.file) return res.status(400).json({ error: 'avatar file is required' });
  const type = await sniffType(req.file.path);
  if (!type) {
    await rm(req.file.path, { force: true });
    return res.status(415).json({ error: 'only PNG or JPEG images are allowed' });
  }
  res.status(201).json({ id: req.file.filename, type, bytes: req.file.size, originalName: req.file.originalname });
});

app.use((err, req, res, next) =&gt; {
  if (err instanceof multer.MulterError) {
    const status = err.code === 'LIMIT_FILE_SIZE' ? 413 : 400;
    return res.status(status).json({ error: err.message, code: err.code });
  }
  next(err);
});
