test/chat.test.js<pre><code>import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { once } from 'node:events';
import { createChatServer } from '../src/server.js';

const secret = 'test-secret-with-at-least-32-characters!';
let chat, base;

before(async () =&gt; {
  chat = createChatServer({ secret });
  chat.server.listen(0);
  await once(chat.server, 'listening');
  base = `localhost:${chat.server.address().port}`;
});
after(() =&gt; chat.close());

async function login(name) {
  const res = await fetch(`http://${base}/session`, {
    method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }),
  });
  return (await res.json()).token;
}

// Connect and collect messages; next(type) resolves with the next message of that type
async function connect(name) {
  const ws = new WebSocket(`ws://${base}/ws?token=${await login(name)}`);
  const inbox = [];
  const waiters = [];
  ws.addEventListener('message', (e) =&gt; {
    const m = JSON.parse(e.data);
    const i = waiters.findIndex((w) =&gt; w.type === m.type);
    if (i &gt;= 0) waiters.splice(i, 1)[0].resolve(m); else inbox.push(m);
  });
  await once(ws, 'open');
  ws.json = (obj) =&gt; ws.send(JSON.stringify(obj));
  ws.next = (type) =&gt; {
    const i = inbox.findIndex((m) =&gt; m.type === type);
    if (i &gt;= 0) return Promise.resolve(inbox.splice(i, 1)[0]);
    return new Promise((resolve) =&gt; waiters.push({ type, resolve }));
  };
  return ws;
}

test('rejects upgrades without a valid token', async () =&gt; {
  const ws = new WebSocket(`ws://${base}/ws?token=forged.token`);
  const [event] = await once(ws, 'error');
  assert.equal(event.type, 'error');
});

test('messages reach everyone in the room, with history for late joiners', async () =&gt; {
  const alice = await connect('alice');
  const bob = await connect('bob');
  alice.json({ type: 'join', room: 'general' });
  await alice.next('joined');
  bob.json({ type: 'join', room: 'general' });
  const joined = await bob.next('joined');
  assert.equal(joined.online, 2);
  assert.equal((await alice.next('presence')).user, 'bob');

  alice.json({ type: 'say', room: 'general', text: '  hello bob  ' });
  const [a, b] = await Promise.all([alice.next('message'), bob.next('message')]);
  assert.equal(a.text, 'hello bob');
  assert.equal(b.user, 'alice');

  const carol = await connect('carol');
  carol.json({ type: 'join', room: 'general' });
  const late = await carol.next('joined');
  assert.deepEqual(late.history.map((m) =&gt; m.text), ['hello bob']);
  for (const ws of [alice, bob, carol]) ws.close();
});

test('invalid messages and non-members get errors, not crashes', async () =&gt; {
  const eve = await connect('eve');
  eve.send('not json');
  assert.equal((await eve.next('error')).error, 'invalid message');
  eve.json({ type: 'say', room: 'general', text: 'sneaky' });
  assert.equal((await eve.next('error')).error, 'join general first');
  eve.close();
});

test('per-connection rate limit', async () =&gt; {
  const spammer = await connect('spammer');
  spammer.json({ type: 'join', room: 'spam' });
  await spammer.next('joined');
  for (let i = 0; i &lt; 15; i++) spammer.json({ type: 'say', room: 'spam', text: `msg ${i}` });
  assert.equal((await spammer.next('error')).error, 'slow down');
  spammer.close();
});
</code></pre> <pre><code>$ node --test 'test/*.test.js'
✔ rejects upgrades without a valid token
✔ messages reach everyone in the room, with history for late joiners
✔ invalid messages and non-members get errors, not crashes
✔ per-connection rate limit
ℹ tests 4
ℹ pass 4
ℹ fail 0
</code></pre> <p>The helper <code>connect()</code> buffers incoming messages and exposes <code>next(type)</code>, which turns the event stream into awaitable steps — the same idea as <code>events.once</code>, filtered by message type. Tests listen on port <code>0</code> so the OS picks a free port.</p>

slow.mjs<pre><code>// A "report" endpoint's core logic with two hidden inefficiencies
function buildReport(orders) {
  const byCustomer = {};
  for (const o of orders) {
    // 1. Re-sorting the whole array for every order: O(n^2 log n)
    const sorted = [...orders].sort((a, b) =&gt; a.amount - b.amount);
    const rank = sorted.indexOf(o);
    // 2. Building strings by repeated JSON round-trips
    const copy = JSON.parse(JSON.stringify(o));
    (byCustomer[copy.customer] ??= []).push({ ...copy, rank });
  }
  return byCustomer;
}

const orders = Array.from({ length: 3000 }, (_, i) =&gt; ({ id: i, customer: `c${i % 50}`, amount: (i * 7919) % 1000 }));
const t0 = performance.now();
buildReport(orders);
console.log(`report built in ${Math.round(performance.now() - t0)} ms`);
</code></pre> <pre><code>$ node --cpu-prof --cpu-prof-dir=prof slow.mjs
report built in 910 ms
</code></pre> <p>A <code>.cpuprofile</code> is JSON: a tree of call-frame nodes, plus the sequence of sampled node ids and time deltas between samples. You can drag it into Chrome DevTools' Performance panel for a flame chart, or summarize it with a few lines of code:</p> top.mjs<pre><code>// Summarize a .cpuprofile: self time per function, top 6
import { readFileSync, readdirSync } from 'node:fs';
const dir = process.argv[2];
const file = readdirSync(dir).find(f =&gt; f.endsWith('.cpuprofile'));
const { nodes, samples, timeDeltas } = JSON.parse(readFileSync(`${dir}/${file}`, 'utf8'));
const byId = new Map(nodes.map(n =&gt; [n.id, n]));
const self = new Map();
samples.forEach((id, i) =&gt; {
  const { functionName, url, lineNumber } = byId.get(id).callFrame;
  const key = `${functionName || '(anonymous)'} ${url.split('/').pop()}:${lineNumber + 1}`;
  self.set(key, (self.get(key) ?? 0) + (timeDeltas[i] ?? 0));
});
const total = [...self.values()].reduce((a, b) =&gt; a + b, 0);
for (const [k, us] of [...self].sort((a, b) =&gt; b[1] - a[1]).slice(0, 6)) {
  console.log(`${((us / total) * 100).toFixed(1).padStart(5)}%  ${k}`);
}
</code></pre> <pre><code>$ node top.mjs prof
 77.2%  buildReport slow.mjs:2
 16.3%  (anonymous) slow.mjs:6
  2.4%  compileForInternalLoader realm:384
  1.4%  (program) :0
  0.8%  (garbage collector) :0
  0.2%  (idle) :0
</code></pre> <p>The profile points straight at <code>buildReport</code> and the sort comparator on line 6 (built-ins such as <code>Array.prototype.sort</code> and <code>indexOf</code> are attributed to their caller here). The fix is algorithmic, not micro-optimization: sort once, look up ranks in a <code>Map</code>, and replace the JSON round-trip with a shallow copy.</p> fast.mjs<pre><code>function buildReport(orders) {
  const rankOf = new Map(
    [...orders].sort((a, b) =&gt; a.amount - b.amount).map((o, i) =&gt; [o, i]),  // sort once
  );
  const byCustomer = {};
  for (const o of orders) {
    (byCustomer[o.customer] ??= []).push({ ...o, rank: rankOf.get(o) });   // shallow copy
  }
  return byCustomer;
}

const orders = Array.from({ length: 3000 }, (_, i) =&gt; ({ id: i, customer: `c${i % 50}`, amount: (i * 7919) % 1000 }));
const t0 = performance.now();
buildReport(orders);
console.log(`report built in ${(performance.now() - t0).toFixed(1)} ms`);
</code></pre> <pre><code>report built in 1.6 ms
</code></pre> <p>From 910 ms to under 2 ms on the same input. In a server, the first version would have blocked the event loop for nearly a second per report request.</p>

leak.mjs<pre><code>import { createServer } from 'node:http';
import { writeHeapSnapshot } from 'node:v8';

// "Cache" of per-request data that is never evicted: a classic leak
const seen = new Map();

const server = createServer((req, res) =&gt; {
  const id = `${Date.now()}-${Math.random()}`;
  seen.set(id, { headers: req.headers, url: req.url, body: Buffer.alloc(10_000).toString('hex') });
  res.end('ok');
});

server.listen(3500, async () =&gt; {
  const mb = (n) =&gt; (n / 1024 / 1024).toFixed(1);
  for (let round = 1; round &lt;= 4; round++) {
    for (let batch = 0; batch &lt; 20; batch++) {     // 20 batches of 100 concurrent requests
      await Promise.all(Array.from({ length: 100 }, () =&gt; fetch('http://localhost:3500/').then(r =&gt; r.text())));
    }
    globalThis.gc?.();
    const { heapUsed, rss } = process.memoryUsage();
    console.log(`after ${round * 2000} requests: heapUsed=${mb(heapUsed)} MB rss=${mb(rss)} MB entries=${seen.size}`);
  }
  console.log('snapshot written to', writeHeapSnapshot());
  server.close();
});
</code></pre> <pre><code>$ node --expose-gc leak.mjs
after 2000 requests: heapUsed=50.0 MB rss=198.8 MB entries=2000
after 4000 requests: heapUsed=89.0 MB rss=254.1 MB entries=4000
after 6000 requests: heapUsed=127.7 MB rss=285.4 MB entries=6000
after 8000 requests: heapUsed=166.8 MB rss=325.1 MB entries=8000
snapshot written to Heap.20260926.204957.11778.0.001.heapsnapshot
</code></pre> <p>Forcing a GC (<code>--expose-gc</code> and <code>gc()</code>, for diagnosis only) before measuring removes garbage that simply hasn't been collected yet. <code>heapUsed</code> still climbs by ~39 MB per 2,000 requests — about 20 KB per request, which matches the 20,000-character hex string stored for each one. That's a leak.</p> <p>To find the culprit in a real app:</p> <ol> <li>Take a heap snapshot after warm-up, apply load, take another (<code>v8.writeHeapSnapshot()</code>,    the DevTools Memory tab, or <code>node --heapsnapshot-signal=SIGUSR2</code> to write one on a    signal).</li> <li>Load both in DevTools → Memory → select the second → Comparison view against the    first. Sort by # Delta or Size Delta.</li> <li>Pick a growing constructor (here: <code>(string)</code> and <code>Object</code>), open an instance, and read    its Retainers panel: the chain of references keeping it alive. It will lead to    <code>seen</code> → <code>Map</code> → the module scope.</li> </ol> <p>For leaks that only show up in production, <code>--heapsnapshot-near-heap-limit=1</code> writes a snapshot just before the process would run out of heap. Heap snapshots contain your data (including secrets and personal data present in memory) — handle them like production database dumps.</p>

src/money.ts<pre><code>export type Currency = 'USD' | 'EUR' | 'INR';

export interface Money {
  readonly amountMinor: number;   // integer minor units (cents, paise)
  readonly currency: Currency;
}

export function add(a: Money, b: Money): Money {
  if (a.currency !== b.currency) {
    throw new Error(`cannot add ${a.currency} to ${b.currency}`);
  }
  return { amountMinor: a.amountMinor + b.amountMinor, currency: a.currency };
}

export function format(m: Money): string {
  return new Intl.NumberFormat('en', { style: 'currency', currency: m.currency })
    .format(m.amountMinor / 100);
}
</code></pre> src/main.ts<pre><code>import { add, format, type Money } from './money.ts';

const price: Money = { amountMinor: 1999, currency: 'USD' };
const shipping: Money = { amountMinor: 500, currency: 'USD' };
console.log(format(add(price, shipping)));
</code></pre> <pre><code>$ node src/main.ts
$24.99
</code></pre> <p>Note the import: <code>'./money.ts'</code> with the <code>.ts</code> extension, because Node resolves the file exactly as written (ESM rules from Level 1, lesson 03). And <code>type Money</code> is imported with the <code>type</code> modifier, marking it as erased at runtime.</p>

tsconfig.json<pre><code>{
  "compilerOptions": {
    "target": "es2023",
    "module": "nodenext",
    "moduleResolution": "nodenext",
    "strict": true,
    "noEmit": true,
    "allowImportingTsExtensions": true,
    "erasableSyntaxOnly": true,
    "verbatimModuleSyntax": true,
    "skipLibCheck": true
  },
  "include": ["src"]
}
</code></pre> <ul> <li><code>module</code>/<code>moduleResolution: "nodenext"</code> — follow Node's real ESM/CJS rules, including   <code>"type": "module"</code> and <code>exports</code> maps.</li> <li><code>noEmit</code> — <code>tsc</code> only checks; Node runs the <code>.ts</code> files.</li> <li><code>allowImportingTsExtensions</code> — permit <code>./money.ts</code> imports.</li> <li><code>verbatimModuleSyntax</code> — requires <code>import type</code> for type-only imports, so what you write   is exactly what gets erased.</li> <li><code>strict</code> — non-negotiable for new code.</li> </ul> <p>Type stripping does not check types. A file with type errors still runs:</p> src/bad.ts<pre><code>import { add, type Money } from './money.ts';
const a: Money = { amountMinor: 100, currency: 'USD' };
add(a, { amountMinor: '5', currency: 'GBP' });
</code></pre> <pre><code>$ npx tsc
src/bad.ts(3,10): error TS2322: Type 'string' is not assignable to type 'number'.
src/bad.ts(3,28): error TS2322: Type '"GBP"' is not assignable to type 'Currency'.
$ node src/bad.ts
Error: cannot add USD to GBP
