</code></pre> <p>If you publish a library or want the smallest possible startup, you can still compile to JavaScript with <code>tsc</code> (with <code>rewriteRelativeImportExtensions</code> turning <code>.ts</code> imports into <code>.js</code>) and run the output.</p>

demo.js<pre><code>import { createServer } from 'node:http';
import { once } from 'node:events';
import { getJson, circuitBreaker, CircuitOpenError } from './http-client.js';

// A flaky "inventory" service: fails the first 2 calls with 503, then answers
let calls = 0;
let mode = 'flaky';
const inventory = createServer((req, res) =&gt; {
  calls++;
  if (mode === 'down' || (mode === 'flaky' &amp;&amp; calls &lt;= 2)) { res.writeHead(503).end(); return; }
  if (mode === 'slow') { setTimeout(() =&gt; res.end('{}'), 2000); return; }
  res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify({ sku: 'LAMP', inStock: 12 }));
});
inventory.listen(0);
await once(inventory, 'listening');
const url = `http://localhost:${inventory.address().port}/stock/LAMP`;

console.log('flaky -&gt;', await getJson(url), `(server saw ${calls} calls)`);

mode = 'slow';
const t0 = performance.now();
await getJson(url, { timeoutMs: 300, retries: 1 }).catch((e) =&gt; console.log('slow  -&gt;', e.name, `after ${Math.round(performance.now() - t0)} ms`));

mode = 'down';
const breaker = circuitBreaker({ threshold: 3, coolDownMs: 5000 });
calls = 0;
for (let i = 1; i &lt;= 5; i++) {
  try { await breaker.call(() =&gt; getJson(url, { retries: 0 })); }
  catch (e) { console.log(`down  -&gt; call ${i}: ${e instanceof CircuitOpenError ? 'fast fail (circuit open)' : e.message}`); }
}
console.log(`server saw ${calls} calls while down; breaker is ${breaker.state}`);
inventory.closeAllConnections();
inventory.close();
</code></pre> <pre><code>flaky -&gt; { sku: 'LAMP', inStock: 12 } (server saw 3 calls)
slow  -&gt; TimeoutError after 676 ms
down  -&gt; call 1: upstream 503
down  -&gt; call 2: upstream 503
down  -&gt; call 3: upstream 503
down  -&gt; call 4: fast fail (circuit open)
down  -&gt; call 5: fast fail (circuit open)
server saw 3 calls while down; breaker is open
</code></pre> <ul> <li>Flaky: two 503s were retried transparently; the caller got data on the third attempt.</li> <li>Slow: each attempt was cut off at 300 ms; with one retry and backoff the caller got a   <code>TimeoutError</code> after ~676 ms instead of waiting for a 2-second response (or forever).</li> <li>Down: after three consecutive failures the breaker opened, and calls 4 and 5 failed   immediately without touching the network — protecting both the caller's latency and the   struggling service from extra load.</li> </ul> <p>Rules for retries:</p> <ul> <li>Retry only idempotent operations (GET, PUT, DELETE) or requests with an   idempotency key (Level 2, lesson 03). Retrying a plain <code>POST /payments</code> may double-charge.</li> <li>Retry only transient failures: timeouts, connection resets, 502/503/504. Never 400s.</li> <li>Budget retries: with 3 layers of services each retrying 3 times, one user request   can become 27 calls to the bottom service during an outage ("retry storm"). Retry at one   layer, and keep total time within the caller's own deadline.</li> <li>Jitter spreads retries out so thousands of clients don't retry in lockstep.</li> </ul> <p>Mature libraries exist for this (e.g. <code>cockatiel</code> for retry/circuit-breaker/timeout policies; <code>opossum</code> for circuit breakers). The hand-rolled version above shows what they do.</p>

app.mjs<pre><code>import { createServer, get } from 'node:http';
import { trace, SpanStatusCode } from '@opentelemetry/api';

const tracer = trace.getTracer('orders');

// "inventory" service on 4001
createServer((req, res) =&gt; res.end('{"inStock":3}')).listen(4001);

// "orders" service on 4000: calls inventory, and records a custom span for business logic
createServer(async (req, res) =&gt; {
  const stock = await new Promise((resolve) =&gt; get('http://localhost:4001/stock/LAMP', (r) =&gt; {
    let body = ''; r.on('data', (c) =&gt; (body += c)); r.on('end', () =&gt; resolve(JSON.parse(body)));
  }));
  await tracer.startActiveSpan('price-order', async (span) =&gt; {
    span.setAttribute('order.items', 2);
    span.setAttribute('inventory.in_stock', stock.inStock);
    span.setStatus({ code: SpanStatusCode.OK });
    span.end();
  });
  res.end('ok');
}).listen(4000, () =&gt; {
  get('http://localhost:4000/orders', (r) =&gt; r.resume().on('end', () =&gt; setTimeout(() =&gt; process.exit(0), 200)));
});
